mapper.select:
SELECT COUNT(*) FROM pm_project project
WHERE project.id = #{projectId} AND project.tenant_id = #{tenantId} AND project.deleted = 0
  AND (
    project.owner_id = #{userId}
    OR EXISTS (SELECT 1 FROM pm_project_member member WHERE member.project_id = project.id
        AND member.tenant_id = project.tenant_id AND member.user_id = #{userId}
        AND member.status = 1 AND member.deleted = 0)
    OR EXISTS (
      SELECT 1 FROM sys_user_role ur JOIN sys_role role ON role.id = ur.role_id AND role.tenant_id = ur.tenant_id
      WHERE ur.user_id = #{userId} AND ur.tenant_id = #{tenantId} AND role.role_code = 'SUPER_ADMIN'
        AND role.status = 1 AND role.deleted = 0
    )
  )
